def _norm(text: str) -> str:
    return text.replace("*", "").replace("`", "")


def check(at: list[str], src) -> list[str]:
    srcs = [src] if isinstance(src, str) else list(src)
    out: list[str] = []
    for s in srcs:
        p = Path(s)
        if not p.exists():
            out.append(f"missing source {s}")
            continue
        body = _norm(p.read_text(encoding="utf-8", errors="replace"))
        # a token may live in any of the declared sources; collect misses per token
    joined = "\n".join(_norm(Path(s).read_text(encoding="utf-8", errors="replace"))
                       for s in srcs if Path(s).exists())
    for tok in at:
        if _norm(tok) not in joined:
            out.append(f"{'/'.join(srcs)}: string not found: {tok!r}")
    return out


def check_rows(rows: list[dict], fields: tuple[str, ...], src: str) -> list[str]:
    """Verify numeric fields appear in a text artifact (rows.txt style)."""
    p = Path(src)
    if not p.exists():
        return [f"missing source {src}"]
    body = p.read_text(encoding="utf-8", errors="replace")
    bad = []
    for r in rows:
        for f in fields:
            v = r[f]
            token = str(v) if not isinstance(v, float) else f"{v:g}"
            if token not in body and f"{v:.2f}" not in body and f"{v}" not in body:
                bad.append(f"{src}: {r.get('spec') or r.get('arm')} {f}={token} not found")
    return bad


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()

    problems: list[str] = []
    for r in LADDER:
        problems += check(r.pop("at"), r["src"])
    for r in ENCODE_COST:
        problems += check(r.pop("at"), r["src"])
    for r in GAP:
        problems += check(r.pop("at"), r["src"])
    problems += check_rows(MIDRATE, ("bytes", "psnr"), f"{A4}/m50/rows.txt")
    problems += check_rows(COST, ("bytes", "psnr", "decode_s"), f"{A4}/m51/rows_final.txt")
    for r in COLOUR_BUDGET:
        problems += check([f"{r['mb']:.2f} MB", f"{r['psnr']:.2f}"], PN)
    per_at = []
    for r in PERCEPTUAL:
        per_at += [f"{r['mb']:.2f} MB", f"{r['psnr']:.2f}", f"{r['ssim']:.4f}", f"{r['lpips']:.4f}"]
    problems += check(per_at, "experiments/M62_RESULTS.md")
    st_at = []
    for r in STREAMS:
        st_at += [f"{r['raw']:6.2f}", f"{r['coded']:6.2f}"]
    problems += check(st_at, f"{A4}/m24_encode_streams.txt")

    if problems:
        print("PROVENANCE FAIL")
        for p in problems:
            print("  -", p)
        return 1
    print(f"provenance OK: {len(LADDER)} ladder + {len(MIDRATE)} mid-rate + {len(COLOUR_BUDGET)} colour "
          f"+ {len(COST)} cost + {len(ENCODE_COST)} encode + {len(GAP)} gap rows verified")
    if args.check:
        return 0

    res = {"ladder": LADDER, "midrate": MIDRATE, "colour_budget": COLOUR_BUDGET,
           "cost": COST, "encode_cost": ENCODE_COST, "prune_score": PRUNE_SCORE,
           "perceptual": PERCEPTUAL, "streams": STREAMS,
           "bd_rate": BD_RATE, "gap": GAP,
           "meta": {"note": "every row carries the artifact it was read from; "
                            "experiments/j3_ablations.py --check re-verifies"}}
    OUT_JSON.parent.mkdir(parents=True, exist_ok=True)
    OUT_JSON.write_text(json.dumps(res, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    L = ["# J3 — ablation and cost ladder (all rows provenance-checked)\n",
         "## Container ladder (bicycle, 6,131,954 primitives, 25 held-out views)\n",
         "| stage | what it changes | file | B/prim | PSNR | ratio |",
         "|---|---|---|---|---|---|"]
    for r in LADDER:
        L.append(f"| {r['label']} | {r['detail']} | {r['mb']:.2f} MB | {r['bpp']:.2f} | "
                 f"{r['psnr']:.2f} | {r['ratio']:.2f}x |")
    L += ["\n## Geometry bit widths at mid rate (m50, one model)\n",
          "| spec | what it turns | bytes | PSNR | SSIM |", "|---|---|---|---|---|"]
    for r in MIDRATE:
        L.append(f"| `{r['spec']}` | {r['what']} | {r['bytes']:,} | {r['psnr']:.2f} | {r['ssim']:.4f} |")
    L += ["\n## Colour budget at mid rate (m49)\n", "| colour bits | file | PSNR |", "|---|---|---|"]
    for r in COLOUR_BUDGET:
        L.append(f"| {r['bits']} | {r['mb']:.2f} MB | {r['psnr']:.2f} |")
    L += ["\n## Decode cost (m51)\n", "| scene | spec | file | PSNR | SSIM | decode (s) | decode peak (GB) |",
          "|---|---|---|---|---|---|---|"]
    for r in COST:
        L.append(f"| {r['scene']} | `{r['spec']}` | {r['bytes']:,} B | {r['psnr']:.2f} | {r['ssim']:.4f} | "
                 f"{r['decode_s']:.2f} | {r['decode_kb'] / 1e6:.2f} |")
    L += ["\n## Encode/decode stages (m22)\n", "| stage | seconds |", "|---|---|"]
    for r in ENCODE_COST:
        L.append(f"| {r['stage']} | {r['seconds']} |")
    OUT_MD.write_text("\n".join(L) + "\n", encoding="utf-8")
    print(f"wrote {OUT_JSON} and {OUT_MD}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
